BEGIN;
DO $block$
DECLARE payload jsonb := $data$[{"language":"es","old_steps":[{"title":"Pica los vegetales","content":"Pica finamente la cebolla, el pimentón, el ajo y los tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pica los vegetales"},{"title":"Sofríe los aromáticos","content":"Cocina la cebolla, el pimentón y el ajo con el aceite en una olla a fuego medio durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sofríe los aromáticos"},{"title":"Cocina el tomate","content":"Agrega el tomate y cocina 6 minutos, hasta formar un sofrito suave.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cocina el tomate"},{"title":"Prepara el caldo","content":"Añade el agua, la leche de coco y la sal; cocina a fuego suave durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepara el caldo"},{"title":"Cocina el calamar","content":"Incorpora el calamar y mantén un hervor suave durante 15 minutos; si aún está firme, prolonga la cocción hasta que quede tierno antes de añadir el pescado.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cocina el calamar"},{"title":"Añade el pescado","content":"Agrega el pescado en cubos y cocina suavemente durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Añade el pescado"},{"title":"Cocina el camarón","content":"Añade los camarones y cocina durante 3–4 minutos, hasta que estén rosados y opacos; verifica que el pescado esté cocido y el calamar tierno.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cocina el camarón"},{"title":"Sirve la cazuela","content":"Sirve la cazuela caliente con el cilantro opcional. Acompaña con arroz blanco y patacón si lo deseas.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirve la cazuela"}],"new_steps":[{"title":"Pica los vegetales","content":"Pica finamente la cebolla, el pimentón, el ajo y los tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pica los vegetales"},{"title":"Sofríe los aromáticos","content":"Cocina la cebolla, el pimentón y el ajo con el aceite en una olla a fuego medio durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sofríe los aromáticos"},{"title":"Añade el tomate","content":"Agrega el tomate a la olla."},{"title":"Cocina el tomate","content":"Cocínalo durante 6 minutos, hasta que esté suave.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cocina el tomate"},{"title":"Añade los líquidos","content":"Añade el agua, la leche de coco y la sal."},{"title":"Cocina el caldo","content":"Cocina a fuego suave durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Cocina el caldo"},{"title":"Añade el calamar","content":"Incorpora el calamar al caldo."},{"title":"Cocina el calamar","content":"Mantén un hervor suave durante 15 minutos; prolonga la cocción si aún está firme.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cocina el calamar"},{"title":"Añade el pescado","content":"Incorpora el pescado en cubos."},{"title":"Cocina el pescado","content":"Cocina suavemente durante 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Cocina el pescado"},{"title":"Añade los camarones","content":"Incorpora los camarones a la olla."},{"title":"Cocina los camarones","content":"Cocina durante 3–4 minutos, hasta que estén rosados y opacos.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cocina los camarones"},{"title":"Comprueba la cocción","content":"Comprueba que el pescado esté cocido y el calamar tierno."},{"title":"Sirve la cazuela","content":"Sirve la cazuela caliente con cilantro, arroz blanco y patacón al gusto.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirve la cazuela"}]},{"language":"de","old_steps":[{"title":"Gemüse schneiden","content":"Zwiebel, Paprika, Knoblauch und Tomaten fein schneiden.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Gemüse schneiden"},{"title":"Aromaten anschwitzen","content":"Zwiebel, Paprika und Knoblauch im Öl bei mittlerer Hitze 5 Minuten garen.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Aromaten anschwitzen"},{"title":"Tomaten garen","content":"Tomaten zugeben und 6 Minuten weich garen.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Tomaten garen"},{"title":"Brühe zubereiten","content":"Wasser, Kokosmilch und Salz zugeben und 5 Minuten sanft köcheln.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Brühe zubereiten"},{"title":"Tintenfisch garen","content":"Tintenfisch 15 Minuten sanft köcheln lassen; falls er noch fest ist, vor Zugabe des Fischs weitergaren, bis er zart ist.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Tintenfisch garen"},{"title":"Fisch zugeben","content":"Fischwürfel zugeben und 5 Minuten sanft garen.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Fisch zugeben"},{"title":"Garnelen garen","content":"Garnelen zugeben und 3–4 Minuten garen, bis sie rosa und undurchsichtig sind. Fisch und Tintenfisch prüfen.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Garnelen garen"},{"title":"Eintopf servieren","content":"Heiß mit optionalem Koriander servieren. Nach Wunsch weißen Reis und Patacón dazu reichen.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Eintopf servieren"}],"new_steps":[{"title":"Gemüse schneiden","content":"Zwiebel, Paprika, Knoblauch und Tomaten fein schneiden.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Gemüse schneiden"},{"title":"Aromaten anschwitzen","content":"Zwiebel, Paprika und Knoblauch im Öl bei mittlerer Hitze 5 Minuten garen.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Aromaten anschwitzen"},{"title":"Tomaten zugeben","content":"Die Tomaten in den Topf geben."},{"title":"Tomaten garen","content":"6 Minuten weich garen.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Tomaten garen"},{"title":"Flüssigkeit zugeben","content":"Wasser, Kokosmilch und Salz zugeben."},{"title":"Brühe köcheln","content":"5 Minuten sanft köcheln lassen.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Brühe köcheln"},{"title":"Tintenfisch zugeben","content":"Den Tintenfisch in die Brühe geben."},{"title":"Tintenfisch garen","content":"15 Minuten sanft köcheln; falls er noch fest ist, länger garen.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Tintenfisch garen"},{"title":"Fisch zugeben","content":"Die Fischwürfel zugeben."},{"title":"Fisch garen","content":"5 Minuten sanft garen.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Fisch garen"},{"title":"Garnelen zugeben","content":"Die Garnelen in den Topf geben."},{"title":"Garnelen garen","content":"3–4 Minuten garen, bis sie rosa und undurchsichtig sind.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Garnelen garen"},{"title":"Garzustand prüfen","content":"Prüfen, ob der Fisch gar und der Tintenfisch zart ist."},{"title":"Eintopf servieren","content":"Den Eintopf heiß mit Koriander, weißem Reis und Patacón nach Wunsch servieren.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Eintopf servieren"}]},{"language":"en","old_steps":[{"title":"Chop the vegetables","content":"Finely chop the onion, pepper, garlic and tomatoes.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Chop the vegetables"},{"title":"Sauté the aromatics","content":"Cook the onion, pepper and garlic in oil over medium heat for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sauté the aromatics"},{"title":"Cook the tomato","content":"Add the tomato and cook for 6 minutes until soft.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cook the tomato"},{"title":"Make the broth","content":"Add the water, coconut milk and salt; simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Make the broth"},{"title":"Cook the squid","content":"Add the squid and simmer gently for 15 minutes; if still firm, continue until tender before adding the fish.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cook the squid"},{"title":"Add the fish","content":"Add the fish cubes and simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Add the fish"},{"title":"Cook the shrimp","content":"Add the shrimp and cook for 3–4 minutes until pink and opaque. Check the fish is cooked and the squid tender.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cook the shrimp"},{"title":"Serve the stew","content":"Serve hot with optional cilantro. Add white rice and patacón if desired.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Serve the stew"}],"new_steps":[{"title":"Chop the vegetables","content":"Finely chop the onion, pepper, garlic and tomatoes.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Chop the vegetables"},{"title":"Sauté the aromatics","content":"Cook the onion, pepper and garlic in oil over medium heat for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Sauté the aromatics"},{"title":"Add the tomato","content":"Add the tomato to the pot."},{"title":"Cook the tomato","content":"Cook for 6 minutes until soft.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cook the tomato"},{"title":"Add the liquids","content":"Add the water, coconut milk and salt."},{"title":"Simmer the broth","content":"Simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Simmer the broth"},{"title":"Add the squid","content":"Add the squid to the broth."},{"title":"Cook the squid","content":"Simmer gently for 15 minutes, extending the time if it is still firm.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cook the squid"},{"title":"Add the fish","content":"Add the fish cubes."},{"title":"Cook the fish","content":"Simmer gently for 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Cook the fish"},{"title":"Add the shrimp","content":"Add the shrimp to the pot."},{"title":"Cook the shrimp","content":"Cook for 3–4 minutes until pink and opaque.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cook the shrimp"},{"title":"Check doneness","content":"Check that the fish is cooked and the squid tender."},{"title":"Serve the stew","content":"Serve the stew hot with cilantro, white rice and patacón to taste.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Serve the stew"}]},{"language":"fr","old_steps":[{"title":"Hachez les légumes","content":"Hachez finement l’oignon, le poivron, l’ail et les tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Hachez les légumes"},{"title":"Faites revenir les aromates","content":"Faites cuire l’oignon, le poivron et l’ail dans l’huile à feu moyen pendant 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Faites revenir les aromates"},{"title":"Cuisez la tomate","content":"Ajoutez la tomate et laissez cuire 6 minutes jusqu’à ce qu’elle soit tendre.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuisez la tomate"},{"title":"Préparez le bouillon","content":"Ajoutez l’eau, le lait de coco et le sel ; laissez frémir 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Préparez le bouillon"},{"title":"Cuisez le calmar","content":"Ajoutez le calmar et laissez frémir 15 minutes ; s’il est encore ferme, poursuivez jusqu’à ce qu’il soit tendre avant d’ajouter le poisson.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuisez le calmar"},{"title":"Ajoutez le poisson","content":"Ajoutez les dés de poisson et laissez cuire doucement 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Ajoutez le poisson"},{"title":"Cuisez les crevettes","content":"Ajoutez les crevettes et cuisez 3 à 4 minutes jusqu’à ce qu’elles soient roses et opaques. Vérifiez le poisson et le calmar.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuisez les crevettes"},{"title":"Servez la cazuela","content":"Servez chaud avec la coriandre facultative, du riz blanc et un patacón selon vos envies.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servez la cazuela"}],"new_steps":[{"title":"Hachez les légumes","content":"Hachez finement l’oignon, le poivron, l’ail et les tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Hachez les légumes"},{"title":"Faites revenir les aromates","content":"Faites cuire l’oignon, le poivron et l’ail dans l’huile à feu moyen pendant 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Faites revenir les aromates"},{"title":"Ajoutez la tomate","content":"Ajoutez la tomate dans la casserole."},{"title":"Cuisez la tomate","content":"Faites-la cuire 6 minutes jusqu’à ce qu’elle soit tendre.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuisez la tomate"},{"title":"Ajoutez les liquides","content":"Ajoutez l’eau, le lait de coco et le sel."},{"title":"Faites frémir le bouillon","content":"Laissez frémir doucement pendant 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Faites frémir le bouillon"},{"title":"Ajoutez le calmar","content":"Ajoutez le calmar au bouillon."},{"title":"Cuisez le calmar","content":"Laissez frémir 15 minutes ; prolongez la cuisson s’il est encore ferme.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuisez le calmar"},{"title":"Ajoutez le poisson","content":"Ajoutez les dés de poisson."},{"title":"Cuisez le poisson","content":"Faites cuire doucement pendant 5 minutes.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Cuisez le poisson"},{"title":"Ajoutez les crevettes","content":"Ajoutez les crevettes dans la casserole."},{"title":"Cuisez les crevettes","content":"Faites cuire 3 à 4 minutes, jusqu’à ce qu’elles soient roses et opaques.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuisez les crevettes"},{"title":"Vérifiez la cuisson","content":"Vérifiez que le poisson est cuit et que le calmar est tendre."},{"title":"Servez la cazuela","content":"Servez la cazuela chaude avec de la coriandre, du riz blanc et un patacón selon vos envies.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servez la cazuela"}]},{"language":"it","old_steps":[{"title":"Trita le verdure","content":"Trita finemente cipolla, peperone, aglio e pomodori.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Trita le verdure"},{"title":"Soffriggi gli aromi","content":"Cuoci cipolla, peperone e aglio nell’olio a fuoco medio per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Soffriggi gli aromi"},{"title":"Cuoci il pomodoro","content":"Aggiungi il pomodoro e cuoci per 6 minuti, finché morbido.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuoci il pomodoro"},{"title":"Prepara il brodo","content":"Aggiungi acqua, latte di cocco e sale; fai sobbollire per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepara il brodo"},{"title":"Cuoci il calamaro","content":"Aggiungi il calamaro e fai sobbollire per 15 minuti; se è ancora sodo, continua finché tenero prima di aggiungere il pesce.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuoci il calamaro"},{"title":"Aggiungi il pesce","content":"Unisci i cubetti di pesce e cuoci dolcemente per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Aggiungi il pesce"},{"title":"Cuoci i gamberi","content":"Aggiungi i gamberi e cuoci 3–4 minuti finché rosa e opachi. Controlla il pesce e la tenerezza del calamaro.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuoci i gamberi"},{"title":"Servi la cazuela","content":"Servi calda con coriandolo facoltativo e, se vuoi, riso bianco e patacón.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servi la cazuela"}],"new_steps":[{"title":"Trita le verdure","content":"Trita finemente cipolla, peperone, aglio e pomodori.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Trita le verdure"},{"title":"Soffriggi gli aromi","content":"Cuoci cipolla, peperone e aglio nell’olio a fuoco medio per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Soffriggi gli aromi"},{"title":"Aggiungi il pomodoro","content":"Unisci il pomodoro alla pentola."},{"title":"Cuoci il pomodoro","content":"Cuoci per 6 minuti, finché morbido.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cuoci il pomodoro"},{"title":"Aggiungi i liquidi","content":"Unisci acqua, latte di cocco e sale."},{"title":"Cuoci il brodo","content":"Fai sobbollire dolcemente per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Cuoci il brodo"},{"title":"Aggiungi il calamaro","content":"Unisci il calamaro al brodo."},{"title":"Cuoci il calamaro","content":"Fai sobbollire per 15 minuti; prolunga la cottura se è ancora sodo.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cuoci il calamaro"},{"title":"Aggiungi il pesce","content":"Unisci i cubetti di pesce."},{"title":"Cuoci il pesce","content":"Cuoci dolcemente per 5 minuti.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Cuoci il pesce"},{"title":"Aggiungi i gamberi","content":"Unisci i gamberi alla pentola."},{"title":"Cuoci i gamberi","content":"Cuoci per 3–4 minuti, finché rosa e opachi.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cuoci i gamberi"},{"title":"Controlla la cottura","content":"Verifica che il pesce sia cotto e il calamaro tenero."},{"title":"Servi la cazuela","content":"Servi la cazuela calda con coriandolo, riso bianco e patacón a piacere.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Servi la cazuela"}]},{"language":"ja","old_steps":[{"title":"野菜を刻む","content":"玉ねぎ、パプリカ、にんにく、トマトを細かく刻みます。","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"野菜を刻む"},{"title":"香味野菜を炒める","content":"鍋に油を入れ、玉ねぎ、パプリカ、にんにくを中火で5分炒めます。","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"香味野菜を炒める"},{"title":"トマトを煮る","content":"トマトを加え、柔らかくなるまで6分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"トマトを煮る"},{"title":"スープを作る","content":"水、ココナッツミルク、塩を加え、弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"スープを作る"},{"title":"いかを煮る","content":"いかを加えて静かに15分煮ます。まだ硬ければ、魚を加える前に柔らかくなるまで煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"いかを煮る"},{"title":"魚を加える","content":"角切りの魚を加え、弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"魚を加える"},{"title":"えびを煮る","content":"えびを加えて3〜4分、ピンク色で不透明になるまで煮ます。魚の火通りといかの柔らかさも確認します。","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"えびを煮る"},{"title":"盛り付ける","content":"熱いうちに盛り、お好みで香菜を添えます。白いご飯やパタコンも合います。","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"盛り付ける"}],"new_steps":[{"title":"野菜を刻む","content":"玉ねぎ、パプリカ、にんにく、トマトを細かく刻みます。","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"野菜を刻む"},{"title":"香味野菜を炒める","content":"鍋に油を入れ、玉ねぎ、パプリカ、にんにくを中火で5分炒めます。","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"香味野菜を炒める"},{"title":"トマトを加える","content":"鍋にトマトを加えます。"},{"title":"トマトを煮る","content":"柔らかくなるまで6分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"トマトを煮る"},{"title":"水分を加える","content":"水、ココナッツミルク、塩を加えます。"},{"title":"スープを煮る","content":"弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"スープを煮る"},{"title":"いかを加える","content":"スープにいかを加えます。"},{"title":"いかを煮る","content":"静かに15分煮ます。硬ければさらに煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"いかを煮る"},{"title":"魚を加える","content":"角切りの魚を加えます。"},{"title":"魚を煮る","content":"弱火で5分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"魚を煮る"},{"title":"えびを加える","content":"鍋にえびを加えます。"},{"title":"えびを煮る","content":"ピンク色で不透明になるまで3〜4分煮ます。","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"えびを煮る"},{"title":"火通りを確認する","content":"魚に火が通り、いかが柔らかいことを確認します。"},{"title":"盛り付ける","content":"お好みの香菜、白いご飯、パタコンとともに熱々を盛り付けます。","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"盛り付ける"}]},{"language":"pt","old_steps":[{"title":"Pique os vegetais","content":"Pique finamente a cebola, o pimentão, o alho e os tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pique os vegetais"},{"title":"Refogue os aromáticos","content":"Cozinhe a cebola, o pimentão e o alho no azeite em fogo médio por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Refogue os aromáticos"},{"title":"Cozinhe o tomate","content":"Adicione o tomate e cozinhe por 6 minutos, até amolecer.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cozinhe o tomate"},{"title":"Prepare o caldo","content":"Adicione a água, o leite de coco e o sal; cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Prepare o caldo"},{"title":"Cozinhe a lula","content":"Junte a lula e cozinhe em fervura suave por 15 minutos; se ainda estiver firme, cozinhe até amaciar antes de adicionar o peixe.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cozinhe a lula"},{"title":"Adicione o peixe","content":"Junte os cubos de peixe e cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Adicione o peixe"},{"title":"Cozinhe o camarão","content":"Adicione os camarões e cozinhe por 3–4 minutos, até ficarem rosados e opacos. Confira o peixe e a maciez da lula.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cozinhe o camarão"},{"title":"Sirva a caldeirada","content":"Sirva quente com coentro opcional. Acompanhe com arroz branco e patacón, se desejar.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirva a caldeirada"}],"new_steps":[{"title":"Pique os vegetais","content":"Pique finamente a cebola, o pimentão, o alho e os tomates.","image_url":"/recetas/casuela-de-mariscos/paso-01.webp","image_alt":"Pique os vegetais"},{"title":"Refogue os aromáticos","content":"Cozinhe a cebola, o pimentão e o alho no azeite em fogo médio por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-02.webp","image_alt":"Refogue os aromáticos"},{"title":"Adicione o tomate","content":"Junte o tomate à panela."},{"title":"Cozinhe o tomate","content":"Cozinhe por 6 minutos, até amolecer.","image_url":"/recetas/casuela-de-mariscos/paso-03.webp","image_alt":"Cozinhe o tomate"},{"title":"Adicione os líquidos","content":"Junte a água, o leite de coco e o sal."},{"title":"Cozinhe o caldo","content":"Cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-04.webp","image_alt":"Cozinhe o caldo"},{"title":"Adicione a lula","content":"Junte a lula ao caldo."},{"title":"Cozinhe a lula","content":"Cozinhe em fervura suave por 15 minutos; prolongue se ainda estiver firme.","image_url":"/recetas/casuela-de-mariscos/paso-05.webp","image_alt":"Cozinhe a lula"},{"title":"Adicione o peixe","content":"Junte os cubos de peixe."},{"title":"Cozinhe o peixe","content":"Cozinhe em fogo baixo por 5 minutos.","image_url":"/recetas/casuela-de-mariscos/paso-06.webp","image_alt":"Cozinhe o peixe"},{"title":"Adicione os camarões","content":"Junte os camarões à panela."},{"title":"Cozinhe os camarões","content":"Cozinhe por 3–4 minutos, até ficarem rosados e opacos.","image_url":"/recetas/casuela-de-mariscos/paso-07.webp","image_alt":"Cozinhe os camarões"},{"title":"Confira o cozimento","content":"Confira se o peixe está cozido e a lula macia."},{"title":"Sirva a caldeirada","content":"Sirva a caldeirada quente com coentro, arroz branco e patacón a gosto.","image_url":"/recetas/casuela-de-mariscos/paso-08.webp","image_alt":"Sirva a caldeirada"}]}]$data$::jsonb; changed integer;
BEGIN
 PERFORM 1 FROM public.recipes WHERE recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280' FOR UPDATE;
 IF (SELECT count(*) FROM public.recipes r JOIN jsonb_to_recordset(payload) AS p(language text, old_steps jsonb, new_steps jsonb) ON r.language=p.language AND r.steps=p.old_steps WHERE r.recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280' AND r.published) <> 7 THEN RAISE EXCEPTION 'El estado de los pasos ha cambiado'; END IF;
 UPDATE public.recipes r SET steps=p.new_steps FROM jsonb_to_recordset(payload) AS p(language text, old_steps jsonb, new_steps jsonb) WHERE r.recipe_group_id='8e31b609-3fb4-4819-9249-760e0fb73280' AND r.language=p.language;
 GET DIAGNOSTICS changed = ROW_COUNT;
 IF changed <> 7 THEN RAISE EXCEPTION 'Actualización incompleta'; END IF;
END $block$;
COMMIT;
